require_once __DIR__.'/../config/auth.php';require_role(['kasir','owner']);$pageTitle='POS / Pesanan Manual';$menus=dbq('SELECT id,nama,harga,stok FROM menus WHERE is_available=1 AND stok>0 ORDER BY nama')->fetchAll();$tables=dbq('SELECT id,nomor_meja FROM `tables` ORDER BY nomor_meja')->fetchAll();require __DIR__.'/../includes/admin-header.php'; ?>
<div class="max-w-4xl mx-auto"><div class="card p-5 sm:p-7"><p class="section-kicker">point of sale</p><h2 class="font-serif text-3xl mt-2">pesanan langsung</h2><p class="text-sm text-coffee/60 mt-2">buat pesanan untuk pelanggan di kasir. stok akan berkurang otomatis setelah pesanan berhasil dibuat.</p><div id="posMessage" class="flash flash-error hidden mt-5"></div><form id="posForm" class="mt-6 space-y-5"><input type="hidden" name="_csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="action" value="create"><div class="grid sm:grid-cols-2 gap-4"><div><label class="field-label">Nama pelanggan</label><input class="field" name="nama_pelanggan" maxlength="100" value="Pelanggan Langsung" required></div><div><label class="field-label">Nomor meja</label><select class="field" name="table_id"><option value="0">Take away / tidak ada meja</option><?php foreach($tables as $t):?><option value="<?= (int)$t['id'] ?>">Meja <?= h($t['nomor_meja']) ?></option><?php endforeach;?></select></div></div><div><div class="flex items-center justify-between gap-3 mb-3"><h3 class="font-semibold">Item pesanan</h3><button class="btn btn-light !py-2 !px-3 !text-xs" type="button" id="addItem">＋ Tambah item</button></div><div id="itemRows" class="space-y-3"></div><?php if(!$menus):?><p class="text-sm text-red-700">tidak ada menu tersedia dengan stok. tambahkan stok di panel owner dulu.</p><?php endif;?></div><div class="grid sm:grid-cols-2 gap-4"><div><label class="field-label">Metode pembayaran</label><select class="field" name="metode_bayar"><option value="Kasir">Bayar di kasir</option><option value="QRIS">QRIS</option></select></div><div><label class="field-label">Status pembayaran</label><label class="flex items-center gap-3 border border-coffee/10 bg-white rounded-xl p-3"><input type="checkbox" name="paid" value="1" class="accent-[#8A9A5B]"><span><b class="text-sm">Sudah dibayar</b><small class="block text-xs text-coffee/55">centang jika pembayaran sudah diterima.</small></span></label></div></div><div><label class="field-label">Catatan pesanan (opsional)</label><textarea class="field" name="catatan" rows="2" maxlength="800"></textarea></div><div class="flex flex-wrap justify-between items-center gap-3 border-t border-coffee/10 pt-4"><p class="text-xs text-coffee/55">estimasi subtotal belum termasuk pajak/service.</p><button class="btn btn-coffee" type="submit" <?= !$menus?'disabled':'' ?>>Buat Pesanan &amp; Struk →</button></div></form></div></div>
<template id="itemTemplate"><div class="pos-row grid grid-cols-[1fr_84px_38px] sm:grid-cols-[1fr_110px_42px] gap-2 items-end"><div><label class="field-label">Menu</label><select class="field pos-menu" name="items[__INDEX__][menu_id]"><option value="">Pilih menu</option><?php foreach($menus as $m):?><option value="<?= (int)$m['id'] ?>"><?= h($m['nama']) ?> — <?= money($m['harga']) ?> (stok <?= (int)$m['stok'] ?>)</option><?php endforeach;?></select></div><div><label class="field-label">Qty</label><input class="field" type="number" name="items[__INDEX__][qty]" value="1" min="1" max="30"></div><button class="btn btn-light !p-2 !h-11" type="button" data-remove-row aria-label="Hapus item">×</button></div></template>
<script>const itemRows=document.getElementById('itemRows'),itemTpl=document.getElementById('itemTemplate').innerHTML;let idx=0;function addItem(){const wrap=document.createElement('div');wrap.innerHTML=itemTpl.replaceAll('__INDEX__',String(idx++));const row=wrap.firstElementChild;row.querySelector('[data-remove-row]').addEventListener('click',()=>{if(itemRows.children.length>1)row.remove();else{row.querySelector('select').value='';row.querySelector('input').value=1}});itemRows.appendChild(row)}addItem();document.getElementById('addItem').addEventListener('click',addItem);document.getElementById('posForm').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,b=form.querySelector('button[type=submit]'),msg=document.getElementById('posMessage');b.disabled=true;b.textContent='Menyimpan...';msg.classList.add('hidden');try{const r=await fetch(<?= json_encode(BASE_URL.'/api/orders.php') ?>,{method:'POST',body:new FormData(form)});const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.message||'pesanan gagal dibuat.');location.href=<?= json_encode(BASE_URL.'/kasir/receipt.php?kode=') ?>+encodeURIComponent(d.kode_pesanan)}catch(err){msg.textContent=err.message||'koneksi gagal.';msg.classList.remove('hidden')}finally{b.disabled=false;b.textContent='Buat Pesanan & Struk →'}});</script><?php require __DIR__.'/../includes/admin-footer.php'; ?>
